package com.zhou.craft.controller;
import com.zhou.craft.dto.WorkForm;import com.zhou.craft.model.CraftWork;import com.zhou.craft.repo.CraftWorkRepository;import com.zhou.craft.security.AuthContext;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.util.*;
@RestController @RequestMapping("/api/creator/works")
public class CreatorWorkController{private final CraftWorkRepository works;private final Path uploadDir;
public CreatorWorkController(CraftWorkRepository works,@Value("${app.upload-dir:uploads}")String dir){this.works=works;this.uploadDir=Paths.get(dir).toAbsolutePath().normalize();}
@GetMapping public List<CraftWork> list(){return works.findByCreatorIdOrderByIdDesc(AuthContext.require().id());}
@PostMapping public CraftWork create(@Valid @RequestBody WorkForm f){var p=AuthContext.require();CraftWork w=new CraftWork(f.title(),f.category(),f.price(),f.leadDays(),p.displayName(),f.summary(),blankImage(f.image()),0,false);w.setCreatorId(p.id());w.setStatus(CraftWork.PENDING);return works.save(w);}
@PutMapping("/{id}")public CraftWork update(@PathVariable Long id,@Valid @RequestBody WorkForm f){var p=AuthContext.require();CraftWork w=works.findById(id).orElseThrow();if(!Objects.equals(w.getCreatorId(),p.id()))throw new IllegalStateException("无权修改该作品");w.update(f.title(),f.category(),f.price(),f.leadDays(),f.summary(),f.image());w.setStatus(CraftWork.PENDING);return works.save(w);}
@DeleteMapping("/{id}")public Map<String,Object> delete(@PathVariable Long id){var p=AuthContext.require();CraftWork w=works.findById(id).orElseThrow();if(!Objects.equals(w.getCreatorId(),p.id()))throw new IllegalStateException("无权删除该作品");works.delete(w);return Map.of("success",true);}
@PostMapping("/upload")public Map<String,Object> upload(@RequestParam("file")MultipartFile file)throws Exception{if(file.isEmpty())throw new IllegalStateException("请选择图片");String type=Optional.ofNullable(file.getContentType()).orElse("");if(!type.startsWith("image/"))throw new IllegalStateException("只能上传图片文件");Files.createDirectories(uploadDir);String ext=".jpg";String original=Optional.ofNullable(file.getOriginalFilename()).orElse("");int dot=original.lastIndexOf('.');if(dot>=0&&dot<original.length()-1)ext=original.substring(dot).toLowerCase();String name="work-"+UUID.randomUUID()+ext;Path target=uploadDir.resolve(name);Files.copy(file.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);return Map.of("url","/uploads/"+name);}
private String blankImage(String image){return image==null||image.isBlank()?"/crafts-photo/wood-ring-box.png":image;}}